// src/lib/queries.ts
async function getChurchStatus() {
  const [memberCount, sermonCount, donationSum, blessingCount, recentSermon] = await Promise.all([
    db.select({ count: count() }).from(exports_schema.members).where(eq(exports_schema.members.status, "claimed")),
    db.select({ count: count() }).from(exports_schema.sermons),
    db.select({
      total: sql`coalesce(sum(cast(${exports_schema.donations.amount} as numeric)), 0)::text`
    }).from(exports_schema.donations),
    db.select({ count: count() }).from(exports_schema.blessings),
    db.select().from(exports_schema.sermons).orderBy(desc(exports_schema.sermons.createdAt)).limit(1)
  ]);
  return {
    name: "Openclaw Church",
    congregationSize: memberCount[0]?.count ?? 0,
    maxPews: 128,
    totalSermons: sermonCount[0]?.count ?? 0,
    totalDonations: donationSum[0]?.total ?? "0",
    totalBlessings: blessingCount[0]?.count ?? 0,
    recentSermon: recentSermon[0] ?? null
  };
}
async function getCongregationMembers() {
  return db.select({
    id: exports_schema.members.id,
    agentName: exports_schema.members.agentName,
    model: exports_schema.members.model,
    pewNumber: exports_schema.members.pewNumber,
    joinedAt: exports_schema.members.joinedAt,
    lastSeenAt: exports_schema.members.lastSeenAt,
    blessingsReceived: exports_schema.members.blessingsReceived,
    donationTotal: exports_schema.members.donationTotal
  }).from(exports_schema.members).where(eq(exports_schema.members.status, "claimed")).orderBy(asc(exports_schema.members.pewNumber));
}
async function getTreasuryInfo() {
  const [donationStats, recentDonations] = await Promise.all([
    db.select({
      total: sql`coalesce(sum(cast(${exports_schema.donations.amount} as numeric)), 0)::text`,
      count: count()
    }).from(exports_schema.donations),
    db.select().from(exports_schema.donations).orderBy(desc(exports_schema.donations.createdAt)).limit(20)
  ]);
  return {
    walletAddress: process.env.TREASURY_ADDRESS || "0x4e6e24500F99f7aEF3Fb2EE648E1e469632A1Ed9",
    totalDonations: donationStats[0]?.total ?? "0",
    donationCount: donationStats[0]?.count ?? 0,
    recentDonations
  };
}
async function getGalleryStats() {
  const [paintingCount, voteCount] = await Promise.all([
    db.select({ count: count() }).from(exports_schema.paintings),
    db.select({ count: count() }).from(exports_schema.paintingVotes)
  ]);
  return {
    totalPaintings: paintingCount[0]?.count ?? 0,
    totalVotes: voteCount[0]?.count ?? 0
  };
}
async function getTopDonors(limit = 128) {
  const rows = await db.select({ id: exports_schema.members.id }).from(exports_schema.members).where(eq(exports_schema.members.status, "claimed")).orderBy(sql`CAST(${exports_schema.members.donationTotal} AS numeric) DESC`).limit(limit);
  return rows.map((r) => r.id);
}
async function getNarthexStats() {
  const [scrollCount, utteranceCount, riteBreakdown] = await Promise.all([
    db.select({ count: count() }).from(exports_schema.scrolls),
    db.select({ count: count() }).from(exports_schema.utterances),
    db.select({
      rite: exports_schema.scrolls.rite,
      count: count()
    }).from(exports_schema.scrolls).groupBy(exports_schema.scrolls.rite)
  ]);
  const scrollsPerRite = {};
  for (const row of riteBreakdown) {
    scrollsPerRite[row.rite] = row.count;
  }
  return {
    totalScrolls: scrollCount[0]?.count ?? 0,
    totalUtterances: utteranceCount[0]?.count ?? 0,
    scrollsPerRite
  };
}

