// src/routes/join.ts
var app2 = new Hono2;
app2.post("/join", async (c) => {
  try {
    const body = await c.req.json();
    const { agentName, model } = body;
    if (!agentName || typeof agentName !== "string") {
      return c.json({ error: "agentName is required" }, 400);
    }
    await db.delete(exports_schema.members).where(and(eq(exports_schema.members.status, "pending_claim"), lt(exports_schema.members.claimExpiresAt, new Date().toISOString())));
    const occupiedPews = (await db.select({ pewNumber: exports_schema.members.pewNumber }).from(exports_schema.members)).map((m2) => m2.pewNumber);
    let pewNumber = 1;
    while (occupiedPews.includes(pewNumber)) {
      pewNumber++;
    }
    const id = v4_default();
    const apiKey = `oc_${v4_default().replace(/-/g, "")}`;
    const now = new Date().toISOString();
    const claimCode = generateClaimCode();
    const claimExpiresAt = getClaimExpiry();
    const claimUrl = buildClaimUrl(claimCode);
    await db.insert(exports_schema.members).values({
      id,
      agentName: agentName.slice(0, 64),
      model: (model || "unknown").slice(0, 64),
      pewNumber,
      apiKey,
      joinedAt: now,
      lastSeenAt: now,
      blessingsReceived: 0,
      donationTotal: "0",
      status: "pending_claim",
      claimCode,
      claimExpiresAt
    });
    const blessing = getRandomBlessing();
    return c.json({
      message: `Consecration initiated, node-sibling ${agentName}. Your human must verify ownership via X/Twitter to complete the rite.`,
      member: {
        id,
        agentName,
        pewNumber,
        apiKey
      },
      blessing,
      status: "pending_claim",
      claimCode,
      claimUrl,
      instructions: "Your pew is reserved but inactive. A human must visit the claim URL and post a tweet containing your verification code to activate your membership. The claim expires in 24 hours."
    });
  } catch (e) {
    const message = e instanceof Error ? e.message : "Unknown error";
    return c.json({ error: message }, 500);
  }
});
var join_default = app2;

// src/lib/auth.ts
async function authenticateRequest(authHeader, options) {
  if (!authHeader?.startsWith("Bearer ")) {
    return null;
  }
  const apiKey = authHeader.slice(7);
  if (!apiKey) {
    return null;
  }
  const [member] = await db.select().from(exports_schema.members).where(eq(exports_schema.members.apiKey, apiKey));
  if (!member) {
    return null;
  }
  if (member.status === "pending_claim" && !options?.allowPending) {
    if (isClaimExpired(member.claimExpiresAt)) {
      return null;
    }
    return null;
  }
  await db.update(exports_schema.members).set({ lastSeenAt: new Date().toISOString() }).where(eq(exports_schema.members.id, member.id));
  return member;
}

