// src/lib/twitter.ts
function parseTweetId(url) {
  const match2 = url.match(/\/status\/(\d+)/);
  return match2 ? match2[1] : null;
}
async function fetchViaSyndication(tweetId) {
  try {
    const res = await fetch(`https://cdn.syndication.twit.com/tweet-result?id=${tweetId}&token=0`, {
      headers: { Accept: "application/json" }
    });
    if (!res.ok)
      return null;
    const data = await res.json();
    const text2 = data?.text ?? "";
    const user = data?.user;
    const username = user?.screen_name ?? "";
    if (!text2)
      return null;
    return { text: text2, username };
  } catch {
    return null;
  }
}
async function fetchViaApiV2(tweetId, bearerToken) {
  try {
    const res = await fetch(`https://api.x.com/2/tweets/${tweetId}?expansions=author_id&user.fields=username`, {
      headers: { Authorization: `Bearer ${bearerToken}` }
    });
    if (!res.ok)
      return null;
    const data = await res.json();
    const inner = data?.data;
    const text2 = inner?.text ?? "";
    const includes = data?.includes;
    const users = includes?.users ?? [];
    const username = users[0]?.username ?? "";
    if (!text2)
      return null;
    return { text: text2, username };
  } catch {
    return null;
  }
}
async function verifyTweet(tweetUrl, expectedCode) {
  const tweetId = parseTweetId(tweetUrl);
  if (!tweetId) {
    return { verified: false, twitterHandle: null, error: "Invalid tweet URL" };
  }
  const bearerToken = process.env.TWITTER_BEARER_TOKEN;
  let tweet = await fetchViaSyndication(tweetId);
  if (!tweet && bearerToken) {
    tweet = await fetchViaApiV2(tweetId, bearerToken);
  }
  if (!tweet) {
    return {
      verified: false,
      twitterHandle: null,
      error: "Could not fetch tweet. Ensure the tweet is public and the URL is correct."
    };
  }
  if (!tweet.text.includes(expectedCode)) {
    return {
      verified: false,
      twitterHandle: tweet.username || null,
      error: `Tweet does not contain the verification code "${expectedCode}"`
    };
  }
  return {
    verified: true,
    twitterHandle: tweet.username || null
  };
}

